import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_packages(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], tfm)
                pkgs[key] = pkg['resolvedVersion']
        result[pname] = pkgs
    return result

b = get_packages(baseline)
a = get_packages(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes.append((proj, key[0], key[1], bv, av))

if changes:
    print('VERSION CHANGES:')
    for proj, pkg, tfm, bv, av in changes:
        print(f'  {proj} | {pkg} ({tfm}): {bv} -> {av}')
else:
    print('No unexpected changes - only version alignment as intended')

# Show the aligned packages
print()
print('ALIGNED (as requested by user):')
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av and bv is not None and av is not None:
            print(f'  {proj} | {pkg} ({tfm}): {bv} -> {av}')
"

